/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function FollowerRushFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function FollowerRushHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its followers as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const FollowerRushStageInner = forwardRef<
  HTMLDivElement,
  FollowerRushStageProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per follower on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every follower the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<FollowerRushFollowerProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const rest = { ...FollowerRushDefaults, ...props };
    // What Studio is doing to each follower that the file may not have yet.
    const [live, setLive] = useState<Record<number, FollowerRushFollowerState>>(
      {},
    );
    const report = (j: number, state: FollowerRushFollowerState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all.map((_, j) => j);
    const built = FollowerRushFromItems(
      kept.map((j) => merged[j] as FollowerRushFollowerValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...FollowerRushFromItems(all.map((o) => o.props)),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Follower Rush"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 305,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: -209,
              width: 1280,
              height: 720,
            }}
          >
            <FollowerRushFade>
              <FollowerRushHosted host={host}>
                <FollowerRushScene key={key} {...rest} {...built} />
              </FollowerRushHosted>
            </FollowerRushFade>
          </div>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: FollowerRushFollowerState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

const FollowerRushStage = Interactive.withSchema({
  Component: FollowerRushStageInner,
  componentName: "<FollowerRushStage>",
  schema: FollowerRushStageSchema,
  supportsEffects: false,
});

